const norm=s=>s.toLowerCase().normalize('NFKC').replace(/[\u00ad\u200b]/g,'').replace(/[‘’`´]/g,"'").replace(/[“”„]/g,'"').replace(/[‐‑‒–—−]/g,'-').replace(/\s+/g,' ').trim();
const sq=s=>s.replace(/[\s\-|]+/g,'');
const fold=s=>s.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7e\n]/g,' ');
const tk=s=>fold(s).split(/[^a-z0-9,.]+/).map(w=>w.replace(/^[.,]+|[.,]+$/g,'')).filter(w=>w.length>1||/\d/.test(w));
let pdfjs=null;
async function pdfText(buf){ if(!pdfjs){ pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.min.mjs'); pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.worker.min.mjs'; }
  const doc=await pdfjs.getDocument({data:buf}).promise; let out=''; for(let p=1;p<=doc.numPages;p++){ const c=await (await doc.getPage(p)).getTextContent(); out+=c.items.map(i=>i.str+(i.hasEOL?'\n':' ')).join('')+'\n'; } return out; }
async function getText(u){ const c=new AbortController; setTimeout(()=>c.abort(),60e3); const r=await fetch(u,{signal:c.signal}); if(!r.ok) throw new Error('status '+r.status); const ct=r.headers.get('content-type')||'';
  if(/pdf|octet/.test(ct)||/\.pdf($|\?)/i.test(u)||/\/PDF$/.test(u)) return await pdfText(await r.arrayBuffer());
  const h=await r.text(); if(!/</.test(h.slice(0,2000))) return h; const d=new DOMParser().parseFromString(h,'text/html'); d.querySelectorAll('script,style,noscript').forEach(e=>e.remove()); d.querySelectorAll('br,p,div,li,tr,td,th,h1,h2,h3,h4,dt,dd').forEach(e=>e.append('\n')); return (d.body?d.body.textContent:h); }
function numPats(value){const out=[];const m=String(value).match(/\d[\d.,\u00a0 ]*\d|\d/g)||[];for(let n of m){n=n.replace(/[\u00a0 ]/g,'');let intp=n,dec='';const mm=n.match(/^(.*)[.,](\d{1,2})$/);if(mm&&!/^\d{1,3}([.,]\d{3})+$/.test(n)){intp=mm[1];dec=mm[2];}intp=intp.replace(/[.,]/g,'');if(!intp)continue;let g=intp.length>3?intp.replace(/\B(?=(\d{3})+(?!\d))/g,'[.,\\u00a0 ]?'):intp;out.push(new RegExp('(?<![\\d])'+g+(dec?'[.,]'+dec.replace(/0+$/,'')+'0*':'(?:[.,]0+)?')+'(?![\\d])'));}return out;}
function cand(t,label,value){const pats=numPats(value);const q=new Set(tk(label+' '+String(value).replace(/\d+/g,' ')));const u=[];for(const line of t.split(/\n+/)){const l=line.replace(/\s+/g,' ').trim();if(!l)continue;if(l.length<260){u.push(l);continue;}for(const p of l.split(/(?<=[.!?])\s+(?=[A-ZČŠŽ0-9"(])/))if(p.trim())u.push(p.trim());}
  let b=null;for(let i=0;i<u.length;i++){let w='';for(let j=i;j<Math.min(u.length,i+3);j++){w=w?w+' '+u[j]:u[j];if(w.length>420)break;const ws=new Set(tk(w));if(!ws.size)continue;let hit=0;for(const x of q)if(ws.has(x))hit++;const nums=pats.filter(p=>p.test(w)).length;const score=(q.size?hit/q.size:0)*2+hit/ws.size+nums*(pats.length?1.5/pats.length:0)-w.length/3000;if(!b||score>b.score)b={score,w,nums,np:pats.length};}}
  return b?b.nums+'/'+b.np+' '+b.w.slice(0,260):'none';}
function check(t,quote){const N=norm(t),q=norm(quote).replace(/\s*\.\.\.\s*|\s*…\s*/g,'\u0001').split('\u0001').filter(p=>p.length>3);if(q.length&&q.every(p=>N.includes(p)))return 'L';const S=sq(N);if(q.length&&q.every(p=>sq(p).length>5&&S.includes(sq(p))))return 'S';
  const F=fold(t).replace(/\s+/g,' ');const w=[...new Set(tk(quote.replace(/\|/g,' ')))];const pos=w.map(x=>{const a=[];const re=new RegExp('(?<![a-z0-9])'+x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?![a-z0-9])','g');let m;while((m=re.exec(F))&&a.length<300)a.push(m.index);return a;});
  if(!pos.every(a=>a.length))return 'N('+w.filter((x,i)=>!pos[i].length).slice(0,4).join(' ')+')';const r=pos.map((a,i)=>[a.length,i]).sort((x,y)=>x[0]-y[0])[0][1];for(const p of pos[r]){if(pos.every(a=>a.some(x=>Math.abs(x-p)<=450)))return 'T';}return 'F';}
export const texts={};
export async function run(only){ const o=location.origin.replace('//www.','//'); const out=[]; for(const [u,L] of Object.entries(D)){ if(new URL(u).origin.replace('//www.','//')!==o) continue; if(only&&!u.includes(only)) continue; let t; try{ t=texts[u]||(texts[u]=await getText(new URL(u).pathname+new URL(u).search)); }catch(e){ out.push('ERR '+u.slice(-40)+' '+String(e.message).slice(0,50)); continue; }
    out.push('# '+u.slice(-46)+' len '+t.length); for(const [id,i,quote,value,label] of L) out.push(id+'#'+i+(quote?'='+check(t,quote):'?'+cand(t,label,value))); }
  window.__zt=texts; return out.join('\n'); }
export function grab(part,re,flags){ const u=Object.keys(texts).find(k=>k.includes(part)); if(!u) return 'no text'; const m=texts[u].replace(/\s+/g,' ').match(new RegExp(re,flags||'')); return m?m[0]:'no match'; }
